<?php
function prc_requests($bid,$status=null){$q=db()->prepare("SELECT r.*,u.name requested_name,a.name approved_name FROM transaction_reversals r JOIN inflows i ON i.id=r.source_id LEFT JOIN users u ON u.id=r.requested_by LEFT JOIN users a ON a.id=r.approved_by WHERE r.source_type='Receipt Item' AND i.batch_id=?".($status?' AND r.status=?':'').' ORDER BY r.id');$q->execute($status?[$bid,$status]:[$bid]);return $q->fetchAll();}
function prc_allocation($b){$m=json_decode($b['result_json']??'[]',true)?:[];$a=$m['incoming_allocation']??null;if(!$a)return null;foreach(prc_requests($b['id'],'Approved') as $r){$p=json_decode($r['result_json'],true);$from=$p['from_id'];$to=$p['to_id'];$a['lines'][$to]??=['product'=>$p['to_name'],'incoming'=>0,'damaged'=>false,'Shopee'=>0,'Lazada'=>0,'TikTok'=>0,'Website'=>0,'Warehouse'=>0,'Non-Sellable'=>0];$a['lines'][$from]['incoming']-=$p['qty'];$a['lines'][$to]['incoming']+=$p['qty'];foreach($p['split'] as $pl=>$n){$a['lines'][$from][$pl]-=$n;$a['lines'][$to][$pl]+=$n;}$a['item_corrections'][]=$r['id'];}return $a;}
function prc_blocked($raw){$flags=json_decode(setting('receipt_mapping_review_v1','{}'),true)?:[];return isset($flags[norm($raw)]);}
function prc_identity($text){if($id=product_code_lookup($text))return (int)$id;$q=db()->prepare('SELECT id FROM products WHERE normalized_name=? LIMIT 1');$q->execute([norm($text)]);return (int)$q->fetchColumn();}
function prc_plan($bid,$stageId,$target,$input=[]){
 $q=db()->prepare('SELECT * FROM inflow_batches WHERE id=?');$q->execute([(int)$bid]);$b=$q->fetch();if(!$b||$b['batch_type']!=='Receipt PDF'||$b['status']!=='Confirmed')throw new Exception('Select a posted Receipt PDF batch.');
 $q=db()->prepare("SELECT COUNT(*) FROM transaction_reversals WHERE source_type='Inflow' AND source_id=? AND status='Pending'");$q->execute([$bid]);if($q->fetchColumn())throw new Exception('A whole-batch reversal is pending. Resolve it first.');
 $q=db()->prepare('SELECT * FROM receipt_staging_lines WHERE batch_id=? ORDER BY line_no,id');$q->execute([$bid]);$stages=$q->fetchAll();$q=db()->prepare("SELECT * FROM inflows WHERE batch_id=? AND type='Receipt Delivery' ORDER BY id");$q->execute([$bid]);$original=$q->fetchAll();if(count($stages)!==count($original))throw new Exception('Original receipt lines cannot be safely linked. Review the batch evidence first.');$source=null;$line=null;foreach($stages as $i=>$s){$o=$original[$i];if((int)$s['product_id']!==(int)$o['product_id']||(int)$s['final_qty']!==(int)$o['qty'])throw new Exception('Original receipt evidence changed. Correction requires investigation.');if((int)$s['id']===(int)$stageId){$source=$o;$line=$s;}}if(!$source||$source['reversed_by_request']!==null||(int)$source['qty']<=0)throw new Exception('Select an active original posted receipt line.');
 $q=db()->prepare("SELECT COUNT(*) FROM transaction_reversals WHERE source_type='Receipt Item' AND source_id=? AND status='Approved'");$q->execute([$source['id']]);if($q->fetchColumn())throw new Exception('This original line already has an approved correction. Review its linked correction history.');
 $to=active_product((int)$target);$from=stock_row((int)$source['product_id']);if((int)$to['id']===(int)$from['id'])throw new Exception('Choose a different correct product / SKU.');$qty=(int)$source['qty'];$a=prc_allocation($b);$bucket=$a['lines'][$from['id']]??null;if(!$bucket||(int)($bucket['Warehouse']??0)!==0||(int)($bucket['Non-Sellable']??0)!==0)throw new Exception('A complete platform allocation is required; legacy warehouse / restricted quantities need separate review.');
 $manual=array_filter($input['allocation']??[],fn($v)=>trim((string)$v)!=='');$split=[];foreach(['Shopee','Lazada','TikTok','Website'] as $pl){$n=$manual?whole_number($input['allocation'][$pl]??0,$pl.' quantity'):(int)($bucket[$pl]??0);if($n>(int)($bucket[$pl]??0))throw new Exception('Correction exceeds the remaining saved '.$pl.' allocation.');$split[$pl]=$n;}if(array_sum($split)!==$qty)throw new Exception('For a product appearing on multiple receipt lines, enter the exact original platform split for this selected line. It must total '.$qty.' pcs.');
 $verified=trim((string)($input['verified_description']??''));if($verified===''||mb_strlen($verified)>500)throw new Exception('Enter the correct item description verified against the original PDF.');$identity=prc_identity($verified);if($identity&&$identity!==(int)$to['id'])throw new Exception('The verified description belongs to another Product Master item. Check the original PDF and correct SKU.');$raw=$line['raw_item'];$rawIdentity=prc_identity($raw);$blockRaw=$rawIdentity&&$rawIdentity!==(int)$to['id'];$aliases=array_unique(array_filter([$verified,$blockRaw?'':$raw]));$before=[];foreach($aliases as $text){$q=db()->prepare('SELECT product_id FROM receipt_aliases WHERE normalized_alias=?');$q->execute([norm($text)]);$before[norm($text)]=$q->fetchColumn()?:null;}
 $moves=[];foreach($split as $pl=>$n)if($n){$moves[]=['pid'=>(int)$from['id'],'platform'=>$pl,'delta'=>-$n];$moves[]=['pid'=>(int)$to['id'],'platform'=>$pl,'delta'=>$n];}
 $p=['type'=>'Receipt Item','batch_id'=>(int)$bid,'stage_id'=>(int)$stageId,'source_id'=>(int)$source['id'],'reference'=>$b['batch_ref'].' · receipt line '.$line['line_no'],'from_id'=>(int)$from['id'],'from_name'=>$from['master_sku'].' · '.$from['name'],'to_id'=>(int)$to['id'],'to_name'=>$to['master_sku'].' · '.$to['name'],'qty'=>$qty,'split'=>$split,'platforms'=>$moves,'raw_item'=>$raw,'verified_description'=>$verified,'aliases'=>$aliases,'aliases_before'=>$before,'block_raw'=>(bool)$blockRaw,'block_before'=>prc_blocked($raw),'original_source'=>$source,'original_allocation'=>$a,'physical_delta'=>0];$p['signature']=hash('sha256',json_encode($p));return $p;
}
function prc_stock_check($p){unset($GLOBALS['OM_RESERVED']);foreach([$p['from_id'],$p['to_id']] as $pid)check_platform_alignment($pid);foreach($p['split'] as $pl=>$qty)if(platform_qty($pl,$p['from_id'])-om_reserved($p['from_id'],$pl)<$qty)throw new Exception('Insufficient unreserved '.$pl.' stock for the wrong product. Review dependent orders / transfers before correction.');if(stock_row($p['from_id'])['available']<$p['qty'])throw new Exception('Insufficient available sellable quantity for this correction.');}
function prc_request($input){if(!can_action('resolve_receipt_line'))throw new Exception('Receipt correction permission required.');if(empty($input['physical_ack']))throw new Exception('Verify the actual item and quantity against the original receipt.');$reason=process_reason($input['reason']??'');return process_transaction(function()use($input,$reason){$bid=(int)($input['batch_id']??0);db()->prepare('SELECT id FROM inflow_batches WHERE id=? FOR UPDATE')->execute([$bid]);$p=prc_plan($bid,(int)($input['stage_id']??0),(int)($input['to_id']??0),$input);$q=db()->prepare("SELECT COUNT(*) FROM transaction_reversals WHERE source_type='Receipt Item' AND source_id=? AND status IN ('Pending','Approved')");$q->execute([$p['source_id']]);if($q->fetchColumn())throw new Exception('A correction already exists for this original receipt line.');prc_stock_check($p);db()->prepare("INSERT INTO transaction_reversals(source_type,source_id,reason,requested_by,result_json) VALUES('Receipt Item',?,?,?,?)")->execute([$p['source_id'],$reason,current_user()['id'],json_encode($p)]);$id=(int)db()->lastInsertId();audit('Request posted receipt item correction','Inflow Batch',$p['reference'],'REV-'.$id.'; '.$reason.'; no stock or mapping changed.');return $id;});}
function prc_approve($id){if(current_user()['role']!=='Admin')throw new Exception('Admin approval required.');return process_transaction(function()use($id){$q=db()->prepare('SELECT * FROM transaction_reversals WHERE id=? FOR UPDATE');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['source_type']!=='Receipt Item'||$r['status']!=='Pending')throw new Exception('Correction is no longer pending.');if((int)$r['requested_by']===current_user()['id'])throw new Exception('A different Admin must approve your request.');$saved=json_decode($r['result_json'],true);db()->prepare('SELECT id FROM inflow_batches WHERE id=? FOR UPDATE')->execute([$saved['batch_id']]);$ids=[$saved['from_id'],$saved['to_id']];sort($ids,SORT_NUMERIC);foreach($ids as $pid)db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$pid]);$p=prc_plan($saved['batch_id'],$saved['stage_id'],$saved['to_id'],['allocation'=>$saved['split'],'verified_description'=>$saved['verified_description']]);if(!hash_equals($saved['signature'],$p['signature']))throw new Exception('Source allocation, product or mapping changed. Reject and submit a fresh correction.');prc_stock_check($p);$date=date('Y-m-d');require_open_inventory_date($date);$ref='REV-'.$id;$note='Posted receipt item correction; '.$p['reference'].'; '.$r['reason'];
 foreach([[$p['from_id'],-$p['qty']],[$p['to_id'],$p['qty']]] as [$pid,$qty])db()->prepare("INSERT INTO inflows(batch_id,txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,conversion_factor,qty,type,remarks,user_id) VALUES(?,?,?,?,'',?,?,'pc',1,?,'Receipt Item Correction',?,?)")->execute([$p['batch_id'],$date,$ref,$p['reference'],$pid,$qty,$qty,$note,current_user()['id']]);foreach($p['platforms'] as $m)if($m['delta'])change_platform_stock($m['platform'],$m['pid'],$m['delta'],$ref,$date);foreach($ids as $pid)check_platform_alignment($pid);
 foreach($p['aliases'] as $text)db()->prepare('INSERT INTO receipt_aliases(normalized_alias,alias,product_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE product_id=VALUES(product_id),alias=VALUES(alias)')->execute([norm($text),$text,$p['to_id']]);if($p['block_raw']){$flags=json_decode(setting('receipt_mapping_review_v1','{}'),true)?:[];$flags[norm($p['raw_item'])]=['request_id'=>$id,'reason'=>'Original PDF extraction conflicts with a valid different product identity; manual verification required'];set_setting('receipt_mapping_review_v1',json_encode($flags));}
 db()->prepare("UPDATE transaction_reversals SET status='Approved',approved_by=?,approved_at=NOW() WHERE id=?")->execute([current_user()['id'],$id]);audit('Approve posted receipt item correction','Inflow Batch',$p['reference'],$ref.'; -'.$p['qty'].' '.$p['from_name'].'; +'.$p['qty'].' '.$p['to_name'].'; net physical change 0; exact receipt mapping reviewed.');return $ref;});}
function prc_batch_panel($b){if($b['batch_type']!=='Receipt PDF')return;$requests=prc_requests($b['id']);echo '<section class="card"><h3>Posted Receipt Item Corrections</h3>';foreach($requests as $r){$p=json_decode($r['result_json'],true);echo '<div style="padding:12px 0;border-bottom:1px solid #e1e7ef"><b>REV-'.(int)$r['id'].' · '.e($r['status']).'</b><p>'.e($p['from_name']).' −'.(int)$p['qty'].' pcs → '.e($p['to_name']).' +'.(int)$p['qty'].' pcs</p><p class="muted small">'.e($r['reason']).' · Requested by '.e($r['requested_name']).' · '.e($r['created_at']).($r['approved_at']?' · Approved by '.e($r['approved_name']).' · '.e($r['approved_at']):'').'</p><p class="muted small">'.e($p['block_raw']?'Conflicting extracted description requires manual verification on future uploads.':'Verified receipt description mapping will use the correct SKU after approval.').'</p><a class="btn ghost sm" href="?page=corrections&amp;request_id='.(int)$r['id'].'">Review Request / Approval</a></div>';}
 if($b['status']==='Confirmed'&&can_action('resolve_receipt_line')){echo '<details><summary class="btn secondary">Correct Posted Receipt Item</summary><form action="actions.php" method="post" class="stack" style="margin-top:16px" data-confirm="Submit this receipt item correction for Admin review? No stock or mapping changes until approval.">';workflow_hidden('prc_request',['batch_id'=>$b['id'],'return'=>'inflow_batch&id='.$b['id']]);echo '<label>Original receipt line<select name="stage_id" required><option value="">Select the wrong posted line</option>';$q=db()->prepare('SELECT r.*,p.name FROM receipt_staging_lines r JOIN products p ON p.id=r.product_id WHERE batch_id=? ORDER BY line_no');$q->execute([$b['id']]);foreach($q as $line)echo '<option value="'.(int)$line['id'].'">Line '.(int)$line['line_no'].' · '.e($line['name']).' · '.(int)$line['final_qty'].' pcs</option>';echo '</select></label><label>Correct Product / SKU</label>'.picker('to_id','Select the actual received product...',true,'',false).'<label>Correct description on original PDF<input name="verified_description" maxlength="500" required></label><details><summary>Exact platform split — needed only when this product has multiple receipt lines</summary><div class="row">';foreach(['Shopee','Lazada','TikTok','Website'] as $pl)echo '<label>'.e($pl).'<input name="allocation['.$pl.']" type="number" min="0" step="1" placeholder="Auto from saved allocation"></label>';echo '</div></details><label>Reason / supporting reference<textarea name="reason" minlength="3" required></textarea></label><label class="ack"><input type="checkbox" name="physical_ack" value="1" required> I verified the correct item and full line quantity against the original receipt and actual stock.</label><p class="muted small">The full selected line is corrected. Original receipt, movements and allocation stay in history. Approval posts a linked minus/plus correction using the original platform split. Reserved / insufficient stock blocks approval.</p><button class="btn primary">Request Admin Approval</button></form></details>';}
 if(!$requests&&$b['status']!=='Confirmed')echo '<p class="muted small">Only posted receipts can request this correction.</p>';echo '</section>';}
